package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import javax.crypto.*;import javax.crypto.spec.*;import java.util.*;
/** Portable authenticated archive. Only explicit data schemas, never preferences wholesale or keystore keys. */
final class PortableBackup {
 static final int MAX=1500000,ROUNDS=210000;
 static byte[] read(InputStream in)throws Exception{if(in==null)throw new IOException("ファイルを開けません");try(InputStream source=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=source.read(b))!=-1){if(out.size()+n>MAX+128)throw new IOException("バックアップの上限を超えています");out.write(b,0,n);}return out.toByteArray();}}
 static void password(char[] p)throws IOException{if(p.length<12||p.length>128)throw new IOException("パスフレーズは12〜128文字にしてください");}
 static byte[] crypt(int mode,char[] pass,byte[] salt,byte[] iv,byte[] payload)throws Exception{password(pass);PBEKeySpec spec=new PBEKeySpec(pass,salt,ROUNDS,256);byte[] key=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();spec.clearPassword();try{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(mode,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,iv));cipher.updateAAD("LOKI-PORTABLE-1".getBytes(StandardCharsets.US_ASCII));return cipher.doFinal(payload);}finally{Arrays.fill(key,(byte)0);}}
 static byte[] seal(JSONObject doc,char[] pass)throws Exception{validate(doc);byte[] plain=doc.toString().getBytes(StandardCharsets.UTF_8);if(plain.length>MAX)throw new IOException("バックアップの上限です");byte[] salt=new byte[16],iv=new byte[12];SecureRandom random=new SecureRandom();random.nextBytes(salt);random.nextBytes(iv);ByteArrayOutputStream out=new ByteArrayOutputStream();out.write("LOKIBK01".getBytes(StandardCharsets.US_ASCII));out.write(salt);out.write(iv);out.write(crypt(Cipher.ENCRYPT_MODE,pass,salt,iv,plain));return out.toByteArray();}
 static JSONObject open(byte[] data,char[] pass)throws Exception{if(data.length<52||data.length>MAX+128||!new String(data,0,8,StandardCharsets.US_ASCII).equals("LOKIBK01"))throw new IOException("対応バックアップではありません");JSONObject doc;try{doc=new JSONObject(new String(crypt(Cipher.DECRYPT_MODE,pass,Arrays.copyOfRange(data,8,24),Arrays.copyOfRange(data,24,36),Arrays.copyOfRange(data,36,data.length)),StandardCharsets.UTF_8));}catch(Exception e){throw new IOException("復号できません。パスフレーズとファイルを確認してください");}validate(doc);return doc;}
 static JSONObject snapshot(Context c,JSONArray selected)throws Exception{JSONObject d=new JSONObject().put("schema",1).put("archiveId",UUID.randomUUID().toString()).put("at",System.currentTimeMillis());if(MaintenancePolicy.selected(selected,"notes")){JSONArray rows=new JSONArray(),all=PersonalNotes.list(c);for(int i=0;i<all.length();i++){JSONObject v=all.getJSONObject(i);rows.put(new JSONObject().put("id",v.getString("id")).put("text",v.getString("text")).put("kind",v.getString("kind")));}d.put("notes",rows);}if(MaintenancePolicy.selected(selected,"memory")){JSONArray refs=new JSONArray(),all=ImportedMemory.read(c);for(int i=0;i<all.length();i++){JSONObject row=all.getJSONObject(i);refs.put(new JSONObject().put("text",row.optString("summary")).put("topic","確認済み取込記憶"));}JSONArray live=new DynamicMemorySync(c).state().getJSONArray("entries");for(int i=0;i<live.length();i++){JSONObject row=live.getJSONObject(i);refs.put(new JSONObject().put("text",row.optString("content")).put("topic",row.optString("topic")));}d.put("memory",refs);}if(MaintenancePolicy.selected(selected,"settings"))d.put("settings",DisplayPreferences.read(c));validate(d);return d;}
 static void validate(JSONObject d)throws Exception{if(d.getInt("schema")!=1)throw new IOException("保存形式を確認してください");ReviewStore.validId(d.getString("archiveId"));if(!d.has("notes")&&!d.has("memory")&&!d.has("settings"))throw new IOException("保存対象を選んでください");for(Iterator<String> it=d.keys();it.hasNext();)if(!Arrays.asList("schema","archiveId","at","notes","memory","settings").contains(it.next()))throw new IOException("未対応の項目です");if(d.has("notes")){JSONArray a=d.getJSONArray("notes");if(a.length()>100)throw new IOException("メモが多すぎます");Set<String> ids=new HashSet<>();for(int i=0;i<a.length();i++){JSONObject row=a.getJSONObject(i);ReviewStore.validId(row.getString("id"));String text=row.getString("text");if(text.trim().isEmpty()||text.length()>2400||!row.getString("kind").matches("memo|continuation")||!ids.add(row.getString("id")))throw new IOException("メモが不正です");}}if(d.has("memory")){JSONArray a=d.getJSONArray("memory");if(a.length()>500)throw new IOException("記憶が多すぎます");for(int i=0;i<a.length();i++){JSONObject row=a.getJSONObject(i);if(row.getString("text").length()>12000||row.getString("topic").length()>300)throw new IOException("記憶の長さを確認してください");}}if(d.has("settings"))DisplayPreferences.checked(d.getJSONObject("settings"));}
 static JSONObject preview(JSONObject d)throws Exception{validate(d);return new JSONObject().put("archiveId",d.getString("archiveId")).put("at",d.optLong("at")).put("notes",d.optJSONArray("notes")==null?0:d.getJSONArray("notes").length()).put("memory",d.optJSONArray("memory")==null?0:d.getJSONArray("memory").length()).put("hasSettings",d.has("settings"));}
 static synchronized JSONObject restore(Context c,JSONObject d,JSONArray selected)throws Exception{validate(d);int added=0;String archive=d.getString("archiveId");if(MaintenancePolicy.selected(selected,"notes")&&d.has("notes"))synchronized(PersonalNotes.class){JSONArray current=PersonalNotes.all(c),incoming=d.getJSONArray("notes");int required=0;for(int i=0;i<incoming.length();i++){JSONObject row=incoming.getJSONObject(i);String id=restoredId(archive,row.getString("id"));boolean exists=false;for(int j=0;j<current.length();j++)if(id.equals(current.getJSONObject(j).getString("id")))exists=true;if(!exists)required++;}if(current.length()+required>200||PersonalNotes.list(c).length()+required>100)throw new IOException("メモの空き件数が不足しています。復元は開始していません");for(int i=0;i<incoming.length();i++){JSONObject row=incoming.getJSONObject(i);String id=restoredId(archive,row.getString("id"));boolean exists=false;for(int j=0;j<current.length();j++)if(id.equals(current.getJSONObject(j).getString("id")))exists=true;if(!exists){current.put(new JSONObject().put("id",id).put("kind",row.getString("kind")).put("text",row.getString("text")).put("at",System.currentTimeMillis()).put("revision",1).put("restoredArchive",archive));added++;}}ConversationWorkspace.write(c,"personal-notes",new JSONObject().put("items",current));}if(MaintenancePolicy.selected(selected,"memory")&&d.has("memory"))ReviewStore.write(c,"restored-memory",new JSONObject().put("archiveId",archive).put("items",d.getJSONArray("memory")));if(MaintenancePolicy.selected(selected,"settings")&&d.has("settings"))DisplayPreferences.save(c,d.getJSONObject("settings"));return new JSONObject().put("notesAdded",added).put("message","メモ "+added+"件を追加。選択した表示設定を復元。記憶は復元資料として保存し、AIへ自動同期していません。復元資料は今回の選択ファイルに入れ替わります");}
 static String restoredId(String archive,String id){return UUID.nameUUIDFromBytes(("backup:"+archive+":"+id).getBytes(StandardCharsets.UTF_8)).toString();}
 private PortableBackup(){}
}
